/**
 * Render the PPT infographic boards to PNG at 2x, so they stay crisp on a projector and in PDF.
 *
 * These are rendered rather than generated by an image model for one reason: every label is a
 * fact. An image model cannot spell `incois_argo_10d_VAM`, and cannot be trusted to point an
 * arrow at the right box. See ppt/DESIGN-SPEC.md.
 */
import { chromium } from "playwright";
import path from "path";
import { pathToFileURL } from "url";

const root = path.resolve("..");
const src = pathToFileURL(path.join(root, "scripts", "ppt_diagrams.html")).href;
const out = path.join(root, "ppt", "images");

const browser = await chromium.launch();
const page = await browser.newPage({ deviceScaleFactor: 2 });
await page.goto(src, { waitUntil: "networkidle" });
await page.evaluate(() => document.fonts.ready);
await page.waitForTimeout(1200);

const boards = {
  gapmap: "S2-gapmap.png",
  unique: "S2-uniqueness.png",
  arch: "S3-architecture.png",
  stack: "S3-stack.png",
  method: "S3-methodology.png",
  feas: "S4-feasibility.png",
  risks: "S4-risks.png",
  aud: "S5-audience.png",
  ben: "S5-benefits.png",
};

for (const [id, file] of Object.entries(boards)) {
  const box = await page.locator(`#${id}`).boundingBox();
  await page.locator(`#${id}`).screenshot({ path: path.join(out, file) });
  console.log(`rendered ${file}  ${Math.round(box.width)}x${Math.round(box.height)} css px`);
}
await browser.close();
